        uint32_t per_end_int_ena:1;
        /** pes_end_int_ena : R/W; bitpos: [1]; default: 0;
         *  The enable bit for SPI_MEM_PES_END_INT interrupt.
         */
        uint32_t pes_end_int_ena:1;
